namespace Coficab.ActionPlan.Core.Entities;

/// <summary>
/// A report generated by itself, every week or every month: the criteria are kept, and each run saves a report
/// (see <see cref="SavedReport"/>) that the administrators can open. Never deleted: archiving only stops it.
/// </summary>
public class ReportSchedule
{
    public Guid Id { get; set; } = Guid.NewGuid();
    /// <summary>claims | capa-actions</summary>
    public string Kind { get; set; } = "claims";
    public string Title { get; set; } = string.Empty;
    /// <summary>weekly | monthly</summary>
    public string Frequency { get; set; } = "weekly";
    /// <summary>0 = Sunday … 6 = Saturday (weekly)</summary>
    public int DayOfWeek { get; set; } = 1;
    /// <summary>1 … 28 (monthly)</summary>
    public int DayOfMonth { get; set; } = 1;
    /// <summary>Hour of the day, Tunisia time (UTC+1).</summary>
    public int Hour { get; set; } = 7;
    /// <summary>Length of the reported period, ending the day of the run.</summary>
    public int PeriodDays { get; set; } = 30;
    public string CriteriaJson { get; set; } = "{}";
    /// <summary>"id1,id2": the organizations followed when the schedule was made (empty: all).</summary>
    public string? OrganizationIds { get; set; }
    public bool IsActive { get; set; } = true;
    public DateTime NextRunAt { get; set; }
    public DateTime? LastRunAt { get; set; }
    public Guid? LastReportId { get; set; }
    public string? LastError { get; set; }
    public string CreatedBy { get; set; } = string.Empty;
    public string? CreatedByName { get; set; }
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
    public bool IsArchived { get; set; }
    public DateTime? ArchivedAt { get; set; }
}
